functions._daEsc:
function _daEsc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// Decode one stored/CDN audit row → record. Mirrors build_draft._bdAuditDecode
// so the viewer doesn't hard-depend on build_draft being loaded.

functions._daDecode:
function _daDecode(eli, row) {
  if (!row) return Promise.resolve(null);
  function _unpack(env) {
    if (!env || env.payload == null) return null;
    if (!env._bdaZ) { try { return JSON.parse(env.payload); } catch (_e) { return null; } }
    try {
      var bin = atob(env.payload);
      var bytes = new Uint8Array(bin.length);
      for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
      return JSON.parse(window.pako.inflate(bytes, { to: "string" }));
    } catch (_e) { return null; }
  }
  if (row._bdaPlain) return Promise.resolve(_unpack(row._bdaPlain));
  if (row._bdaEnc && typeof window._eliDecryptFromRepo === "function") {
    var cipher = "";
    try { cipher = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_lib_cipher") || "") : ""; } catch (_e) {}
    if (!cipher) return Promise.resolve(null);
    return window._eliDecryptFromRepo(cipher, row._bdaEnc)
      .then(function (env) { return _unpack(env); })
      .catch(function () { return null; });
  }
  return Promise.resolve(null);
}

functions._daDecodeAll:
function _daDecodeAll(eli, rows) {
  return Promise.all((rows || []).map(function (r) { return _daDecode(eli, r); }))
    .then(function (recs) { return recs.filter(Boolean); });
}

// ── Data sources ──────────────────────────────────────────────────────
// OWN: local bd_history rows whose id starts bdaudit_.

functions._daLoadOwn:
function _daLoadOwn(eli) {
  return eli.storage.getAll(_DA_STORE).then(function (rows) {
    var mine = (rows || []).filter(function (r) { return r && typeof r.id === "string" && r.id.indexOf(_DA_PREFIX) === 0; });
    return _daDecodeAll(eli, mine);
  });
}

// FLEET: list audit/*.json from the CDN, fetch each, decode all records.

functions._daListFleetFiles:
function _daListFleetFiles(pat) {
  var url = "https://api.github.com/repos/" + _DA_GH_OWNER + "/" + _DA_GH_REPO + "/contents/audit?t=" + Date.now();
  return fetch(url, { headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json" } })
    .then(function (r) { if (!r.ok) return []; return r.json(); })
    .then(function (list) {
      return (Array.isArray(list) ? list : []).filter(function (f) {
        return f && f.name && /\.json$/.test(f.name) && f.download_url;
      });
    }).catch(function () { return []; });
}

functions._daLoadFleet:
function _daLoadFleet(eli, pat) {
  return _daListFleetFiles(pat).then(function (files) {
    return Promise.all(files.map(function (f) {
      return fetch(f.download_url, { cache: "no-store" })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) { return (j && Array.isArray(j.records)) ? j.records : []; })
        .catch(function () { return []; });
    })).then(function (perFile) {
      var all = [];
      perFile.forEach(function (recs) { all = all.concat(recs); });
      return _daDecodeAll(eli, all);
    });
  });
}

// ── UUID → name lookup (fleet mode) — reuse admin_fleet's shared cache when
// present, else load fleet-identity.enc.json directly. ──

functions._daLoadIdentityLookup:
function _daLoadIdentityLookup(eli, pat) {
  try {
    if (window._eli3_admin_fleet_lookup) return Promise.resolve(window._eli3_admin_fleet_lookup);
  } catch (_e) {}
  if (!pat) return Promise.resolve(null);
  var url = "https://api.github.com/repos/" + _DA_GH_OWNER + "/" + _DA_GH_REPO +
    "/contents/" + encodeURIComponent(_DA_IDENTITY_PATH) + "?t=" + Date.now();
  return fetch(url, { headers: { "Authorization": "Bearer " + pat, "Accept": "application/vnd.github+json" } })
    .then(function (r) { if (!r.ok) return null; return r.json(); })
    .then(function (j) {
      if (!j || !j.content) return null;
      var cipher = "";
      try { cipher = (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_lib_cipher") || "") : ""; } catch (_e) {}
      if (!cipher || typeof window._eliDecryptFromRepo !== "function") return null;
      var blob;
      try { blob = JSON.parse(atob(String(j.content).replace(/\s/g, ""))); } catch (_e) { return null; }
      return window._eliDecryptFromRepo(cipher, blob).then(function (map) {
        try { window._eli3_admin_fleet_lookup = map; } catch (_e2) {}
        return map;
      }).catch(function () { return null; });
    }).catch(function () { return null; });
}

functions._daResolveName:
function _daResolveName(lookup, userId) {
  if (!userId) return "(unknown)";
  if (lookup && lookup[userId]) {
    var e = lookup[userId];
    return e.name || e.displayName || e.email || userId;
  }
  return userId; // fall back to raw UUID
}

functions._daFmtDate:
function _daFmtDate(ts) {
  if (!ts) return "—";
  try {
    var d = new Date(ts);
    return d.toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
  } catch (_e) { return String(ts); }
}

// ── Main entry ──────────────────────────────────────────────────────────

functions.showDraftAudit:
function showDraftAudit(eli, opts) {
  opts = opts || {};
  var mode = opts.mode === "fleet" ? "fleet" : "own";
  var host = (eli && eli.ui && typeof eli.ui.claimOutput === "function") ? eli.ui.claimOutput() : document.getElementById("output");
  if (!host) return;
  host.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_da_root";
  host.appendChild(root);

  var title = mode === "fleet" ? "🛡️ Draft Audit — Fleet" : "📋 My Draft History";
  var sub = mode === "fleet"
    ? "Every Build Draft run across all colleagues. Recipes are decrypted locally; names resolved via the identity lookup."
    : "Every draft you've built — the recipe (template + your Step 1 choices + Step 2 fills) so it can be recreated.";
  root.innerHTML =
    '<div class="_da_header">' +
      '<div class="_da_eyebrow">' + (mode === "fleet" ? "ADMIN · RESTRICTED" : "YOUR ACTIVITY") + '</div>' +
      '<div class="_da_title">' + _daEsc(title) + '</div>' +
      '<div class="_da_sub">' + _daEsc(sub) + '</div>' +
    '</div>' +
    '<div class="_da_controls">' +
      '<input type="text" id="_da_filter" class="_da_filter" placeholder="Filter by CP ref, type, third party…">' +
      '<label class="_da_chk"><input type="checkbox" id="_da_completedonly"> 4-step completions only</label>' +
      '<button class="_da_btn _da_btn_ghost" id="_da_refresh">↻ Refresh</button>' +
    '</div>' +
    '<div class="_da_status" id="_da_status"></div>' +
    '<div class="_da_summary" id="_da_summary"></div>' +
    '<div class="_da_list" id="_da_list"></div>';

  var statusEl = root.querySelector("#_da_status");
  var listEl = root.querySelector("#_da_list");
  var summaryEl = root.querySelector("#_da_summary");
  var filterEl = root.querySelector("#_da_filter");
  var completedEl = root.querySelector("#_da_completedonly");
  function _status(m, k) { statusEl.textContent = m || ""; statusEl.className = "_da_status" + (k ? " _da_status_" + k : ""); }

  var _records = [];
  var _lookup = null;

  function _getPat() {
    try { return (eli.compat && eli.compat.lsGet) ? (eli.compat.lsGet("eli_user_github_pat") || "") : ""; } catch (_e) { return ""; }
  }

  function _load() {
    _status("Loading…");
    if (mode === "fleet") {
      var pat = _getPat();
      if (!pat) { _status("Admin GitHub token missing — import credentials in Admin Data Hub.", "err"); return; }
      Promise.all([_daLoadFleet(eli, pat), _daLoadIdentityLookup(eli, pat)]).then(function (res) {
        _records = res[0] || []; _lookup = res[1] || null;
        _status(_records.length + " run(s) across the fleet.", "ok");
        _render();
      }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
    } else {
      _daLoadOwn(eli).then(function (recs) {
        _records = recs || [];
        _status(_records.length + " of your run(s).", "ok");
        _render();
      }).catch(function (e) { _status("Load failed: " + (e && e.message || "unknown"), "err"); });
    }
  }

  function _filtered() {
    var f = String(filterEl.value || "").trim().toLowerCase();
    var only4 = completedEl.checked;
    return _records.filter(function (r) {
      if (only4 && (r.stepsReached || 0) < 4) return false;
      if (!f) return true;
      var hay = [r.cpRef, r.agreementType, r.cpEntity, r.thirdParty].join(" ").toLowerCase();
      return hay.indexOf(f) !== -1;
    }).sort(function (a, b) { return (b.completedAt || 0) - (a.completedAt || 0); });
  }

  function _render() {
    var rows = _filtered();
    // Summary tiles.
    var byStep = { 1: 0, 2: 0, 3: 0, 4: 0 };
    _records.forEach(function (r) { var s = r.stepsReached || 0; if (byStep[s] != null) byStep[s]++; });
    summaryEl.innerHTML =
      '<div class="_da_tile"><div class="_da_tilen">' + _records.length + '</div><div class="_da_tilel">total runs</div></div>' +
      '<div class="_da_tile _da_t4"><div class="_da_tilen">' + byStep[4] + '</div><div class="_da_tilel">completed (4)</div></div>' +
      '<div class="_da_tile"><div class="_da_tilen">' + byStep[3] + '</div><div class="_da_tilel">reached 3</div></div>' +
      '<div class="_da_tile"><div class="_da_tilen">' + (byStep[1] + byStep[2]) + '</div><div class="_da_tilel">dropped early</div></div>';
    if (!rows.length) { listEl.innerHTML = '<div class="_da_empty">No matching runs.</div>'; return; }
    listEl.innerHTML = rows.map(_daRenderCard.bind(null, mode, _lookup)).join("");
    Array.prototype.forEach.call(listEl.querySelectorAll("[data-da-toggle]"), function (b) {
      b.onclick = function () {
        var card = b.closest("._da_card");
        var det = card.querySelector("._da_details");
        var open = det.style.display !== "none";
        det.style.display = open ? "none" : "block";
        b.textContent = open ? "▶ Recipe" : "▼ Recipe";
      };
    });
  }

  filterEl.oninput = _render;
  completedEl.onchange = _render;
  root.querySelector("#_da_refresh").onclick = _load;
  _load();
}

// Card markup — shared, top-level so it's window-attached. Shows metadata
// row + a collapsible recipe (Step 1 answers + Step 2 fills as key/value).

functions._daRenderCard:
function _daRenderCard(mode, lookup, r) {
  var stepBadge = '<span class="_da_step _da_step_' + (r.stepsReached || 0) + '">Step ' + (r.stepsReached || 0) + '/4</span>';
  var who = (mode === "fleet")
    ? '<span class="_da_who">' + _daEsc(_daResolveName(lookup, r.userId)) + '</span>'
    : '';
  function _kvRows(obj) {
    var keys = Object.keys(obj || {});
    if (!keys.length) return '<div class="_da_kv_empty">— none —</div>';
    return keys.map(function (k) {
      return '<div class="_da_kv"><span class="_da_kv_k">' + _daEsc(k) + '</span><span class="_da_kv_v">' + _daEsc(obj[k]) + '</span></div>';
    }).join("");
  }
  return '<div class="_da_card _da_card_s' + (r.stepsReached || 0) + '">' +
    '<div class="_da_cardhdr">' +
      stepBadge + who +
      '<span class="_da_cardtitle">' + _daEsc(r.cpRef || "(no CP ref)") + ' · ' + _daEsc(r.agreementType || "?") + '</span>' +
      '<span class="_da_carddate">' + _daEsc(_daFmtDate(r.completedAt)) + '</span>' +
    '</div>' +
    '<div class="_da_cardmeta">' +
      '<span><b>Entity:</b> ' + _daEsc(r.cpEntity || "—") + '</span>' +
      '<span><b>Third party:</b> ' + _daEsc(r.thirdParty || "—") + '</span>' +
      '<span><b>Template:</b> ' + _daEsc(r.templateId || "—") + '</span>' +
      '<button class="_da_btn _da_btn_sm" data-da-toggle="1">▶ Recipe</button>' +
    '</div>' +
    '<div class="_da_details" style="display:none;">' +
      '<div class="_da_section_h">Step 1 — Logic choices</div>' + _kvRows(r.step1Answers) +
      '<div class="_da_section_h">Step 2 — Inserted values</div>' + _kvRows(r.step2Fills) +
      '<div class="_da_recipe_note">Template <code>' + _daEsc(r.templateId || "?") + '</code>' +
        (r.templateVersion ? ' @ ' + _daEsc(r.templateVersion) : '') + ' + these choices recreate the draft.</div>' +
    '</div>' +
  '</div>';
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.register) return;

  function _open(mode, statKey) {
    try { if (eli.stats && eli.stats.record && statKey) eli.stats.record(statKey); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showDraftAudit !== "function") {
      eli.log.event("tool", "draft_audit_fn_missing", {});
      if (typeof showToast === "function") showToast("Draft Audit failed to load", "err");
      return;
    }
    try { window.showDraftAudit(eli, { mode: mode }); }
    catch (e) {
      eli.log.event("tool", "draft_audit_failed", { mode: mode, msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: {
      app_draft_audit: function () { _open("own", "appOpenedDraftAudit"); },
      app_admin_draft_audit: function () { _open("fleet", "appOpenedAdminDraftAudit"); },
    },
    draft_audit: { open: function () { _open("own"); }, openFleet: function () { _open("fleet"); } },
  });

  eli.log.event("tool", "draft_audit_initialized", {});
}

